import "jsr:@supabase/functions-js/edge-runtime.d.ts";

const GOOGLE_MAPS_API_KEY = Deno.env.get('GOOGLE_MAPS_API_KEY');

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

Deno.serve(async (req: Request) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { action, input, types, location, radius, components, language, placeId } = await req.json();

    console.log('Google Places Proxy - Action:', action);
    console.log('Google Places Proxy - Input:', input);
    console.log('Google Places Proxy - Types:', types);
    console.log('Google Places Proxy - Location:', location);
    console.log('Google Places Proxy - Radius:', radius);
    console.log('Google Places Proxy - Components:', components);
    console.log('Google Places Proxy - Language:', language);
    console.log('Google Places Proxy - PlaceId:', placeId);

    if (!GOOGLE_MAPS_API_KEY) {
      console.error('GOOGLE_MAPS_API_KEY not configured');
      return new Response(
        JSON.stringify({ error: 'API key not configured' }),
        { 
          status: 500, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    let url = '';

    if (action === 'autocomplete') {
      // Build autocomplete URL with all parameters
      const params = new URLSearchParams({
        input: input || '',
        key: GOOGLE_MAPS_API_KEY,
      });

      // Add optional parameters if provided
      if (types) params.append('types', types);
      if (location) params.append('location', location);
      if (radius) params.append('radius', radius.toString());
      if (components) params.append('components', components);
      if (language) params.append('language', language);

      url = `https://maps.googleapis.com/maps/api/place/autocomplete/json?${params.toString()}`;
      console.log('Autocomplete URL:', url.replace(GOOGLE_MAPS_API_KEY, 'API_KEY_HIDDEN'));
    } else if (action === 'place_details') {
      // Build place details URL
      const params = new URLSearchParams({
        place_id: placeId || '',
        fields: 'geometry,formatted_address,name',
        key: GOOGLE_MAPS_API_KEY,
      });

      url = `https://maps.googleapis.com/maps/api/place/details/json?${params.toString()}`;
      console.log('Place Details URL:', url.replace(GOOGLE_MAPS_API_KEY, 'API_KEY_HIDDEN'));
    } else if (action === 'distance_matrix') {
      // Build distance matrix URL
      const { origins, destinations } = await req.json();
      const params = new URLSearchParams({
        origins: origins || '',
        destinations: destinations || '',
        key: GOOGLE_MAPS_API_KEY,
      });

      url = `https://maps.googleapis.com/maps/api/distancematrix/json?${params.toString()}`;
      console.log('Distance Matrix URL:', url.replace(GOOGLE_MAPS_API_KEY, 'API_KEY_HIDDEN'));
    } else {
      console.error('Invalid action:', action);
      return new Response(
        JSON.stringify({ error: 'Invalid action' }),
        { 
          status: 400, 
          headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
        }
      );
    }

    // Make request to Google Maps API
    const response = await fetch(url);
    const data = await response.json();

    console.log('Google Maps API Response Status:', data.status);
    if (data.error_message) {
      console.error('Google Maps API Error:', data.error_message);
    }

    return new Response(
      JSON.stringify(data),
      { 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
      }
    );
  } catch (error) {
    console.error('Error in google-places-proxy:', error);
    return new Response(
      JSON.stringify({ error: error.message }),
      { 
        status: 500, 
        headers: { ...corsHeaders, 'Content-Type': 'application/json' } 
      }
    );
  }
});

