                  <h3 style="color: #333; margin-top: 0;">👤 DESTINATAIRE</h3>
                  <p><strong>Nom:</strong> ${data.recipientName}</p>
                  <p><strong>Téléphone:</strong> ${data.recipientPhone}</p>
                </div>

                <div style="background-color: #f5f5f5; padding: 15px; border-radius: 8px; margin: 15px 0;">
                  <h3 style="color: #333; margin-top: 0;">📍 ITINÉRAIRE</h3>
                  <p><strong>Départ:</strong> ${data.departureRegion}</p>
                  <p><strong>Destination:</strong> ${destination}</p>
                </div>

                <div style="background-color: #f5f5f5; padding: 15px; border-radius: 8px; margin: 15px 0;">
                  <h3 style="color: #333; margin-top: 0;">📦 DESCRIPTION</h3>
                  <p>${data.description || 'Non spécifiée'}</p>
                </div>

                <div style="background-color: #2E7D32; color: white; padding: 15px; border-radius: 8px; margin: 15px 0;">
                  <h3 style="margin-top: 0;">💰 TARIF TOTAL</h3>
                  <p style="font-size: 24px; font-weight: bold; margin: 0;">${data.pricingTotal.toLocaleString()} FCFA</p>
                </div>

                <p style="color: #666; font-size: 12px;">⏰ ${new Date().toLocaleString('fr-FR', { timeZone: 'Africa/Dakar' })}</p>
              </div>
            `
          })
        });

        if (emailResponse.ok) {
          results.email.success = true;
          console.log('✅ Email sent successfully');
        } else {
          const errorData = await emailResponse.json();
          results.email.error = errorData.message || 'Failed to send email';
          console.error('❌ Email sending failed:', errorData);
        }
      } else {
        results.email.error = 'RESEND_API_KEY not configured';
        console.warn('⚠️ RESEND_API_KEY not found in environment variables');
      }
    } catch (emailError) {
      results.email.error = emailError.message;
      console.error('❌ Email error:', emailError);
    }

    // Send WhatsApp Notification
    try {
      console.log('📱 Sending WhatsApp notification...');

