  valide_par uuid,
  motif_refus text
);

-- 2. Enable RLS
ALTER TABLE recharges_wallet ENABLE ROW LEVEL SECURITY;

-- 3. Create RLS policies
CREATE POLICY "Users can view their own recharge requests"
  ON recharges_wallet
  FOR SELECT
  USING (user_id = current_setting('app.current_user_id', true));

CREATE POLICY "Users can create their own recharge requests"
  ON recharges_wallet
  FOR INSERT
  WITH CHECK (user_id = current_setting('app.current_user_id', true));

-- 4. Create indexes for performance
CREATE INDEX idx_recharges_wallet_wallet_id ON recharges_wallet(wallet_id);
CREATE INDEX idx_recharges_wallet_user_id ON recharges_wallet(user_id);
CREATE INDEX idx_recharges_wallet_statut ON recharges_wallet(statut);
CREATE INDEX idx_recharges_wallet_date_demande ON recharges_wallet(date_demande DESC);
CREATE INDEX idx_recharges_wallet_transaction_id ON recharges_wallet(transaction_id);

